package cli

import "testing"

func TestWhyBlock_PreservesEntireMetadata(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name  string
		block whyBlock
	}{
		{
			name: "preserves entire metadata",
			block: whyBlock{
				StartLine: 17,
				EndLine:   28,
				Commit: whyCommitInfo{
					Hash:      "b550507521abcdef",
					ShortHash: "b550507521",
					Author:    "Victor Gutierrez",
					Email:     "victor@example.com",
					WhenText:  "2 weeks ago",
					Subject:   "Handle interrupt signals",
				},
				Entire: &whyEntireInfo{
					CheckpointID: "a3b2c4d5e6f7",
					Agent:        "Claude Code",
					Summary:      "Add cross-platform signal handling for CLI shutdown.",
					IsFallback:   false,
				},
				CodeLines: []string{"signals := []os.Signal{os.Interrupt}"},
				Detail:    whyDetailCommit,
			},
		},
	}

	for _, tt := range tests {
		tt := tt
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			block := tt.block
			if block.StartLine != 17 {
				t.Fatalf("start line = %d, want %d", block.StartLine, 17)
			}
			if block.EndLine != 28 {
				t.Fatalf("end line = %d, want %d", block.EndLine, 28)
			}
			if block.Commit.Hash != "b550507521abcdef" {
				t.Fatalf("commit hash = %q, want %q", block.Commit.Hash, "b550507521abcdef")
			}
			if block.Commit.ShortHash != "b550507521" {
				t.Fatalf("short hash = %q, want %q", block.Commit.ShortHash, "b550507521")
			}
			if block.Commit.Author != "Victor Gutierrez" {
				t.Fatalf("author = %q, want %q", block.Commit.Author, "Victor Gutierrez")
			}
			if block.Commit.Email != "victor@example.com" {
				t.Fatalf("email = %q, want %q", block.Commit.Email, "victor@example.com")
			}
			if block.Commit.WhenText != "2 weeks ago" {
				t.Fatalf("when text = %q, want %q", block.Commit.WhenText, "2 weeks ago")
			}
			if block.Commit.Subject != "Handle interrupt signals" {
				t.Fatalf("subject = %q, want %q", block.Commit.Subject, "Handle interrupt signals")
			}
			if block.Entire == nil {
				t.Fatal("expected Entire metadata")
			}
			if block.Entire.CheckpointID != "a3b2c4d5e6f7" {
				t.Fatalf("checkpoint id = %q, want %q", block.Entire.CheckpointID, "a3b2c4d5e6f7")
			}
			if block.Entire.Agent != "Claude Code" {
				t.Fatalf("agent = %q, want %q", block.Entire.Agent, "Claude Code")
			}
			if block.Entire.Summary != "Add cross-platform signal handling for CLI shutdown." {
				t.Fatalf("summary = %q, want %q", block.Entire.Summary, "Add cross-platform signal handling for CLI shutdown.")
			}
			if block.Entire.IsFallback {
				t.Fatal("expected non-fallback entire metadata")
			}
			if len(block.CodeLines) != 1 {
				t.Fatalf("code line count = %d, want %d", len(block.CodeLines), 1)
			}
			if block.CodeLines[0] != "signals := []os.Signal{os.Interrupt}" {
				t.Fatalf("code line = %q, want %q", block.CodeLines[0], "signals := []os.Signal{os.Interrupt}")
			}
			if block.Detail != whyDetailCommit {
				t.Fatalf("detail = %q, want %q", block.Detail, whyDetailCommit)
			}
			if got, want := block.RangeText(), "17-28"; got != want {
				t.Fatalf("range text = %q, want %q", got, want)
			}
		})
	}
}

