func selectWhySummary(summary *checkpoint.Summary, commitSubject string) (string, bool) {
	if summary != nil {
		if text := strings.TrimSpace(summary.Outcome); text != "" {
			return text, false
		}
		if text := strings.TrimSpace(summary.Intent); text != "" {
			return text, true
		}
	}

	if text := strings.TrimSpace(commitSubject); text != "" {
		return text, true
	}

	return "", true
}

func commitSubject(message string) string {
	subject, _, found := strings.Cut(message, "\n")
	if found {
		return strings.TrimSpace(subject)
	}
	return strings.TrimSpace(message)
}

func newWhyCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "why <path>",
		Short: "Show why lines exist in a file",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			blocks, err := loadWhyDisplayData(ctx, args[0])
			if err != nil {
				return fmt.Errorf("loading why data for %s: %w", args[0], err)
			}

			if err := writeWhyStaticOutput(cmd.OutOrStdout(), renderWhyStatic(blocks)); err != nil {
				return fmt.Errorf("writing why output for %s: %w", args[0], err)
			}
			return nil
		},
	}

	return cmd
}

package cli

import (
	"fmt"
	"strings"
)

func renderWhyStatic(blocks []whyBlock) string {
	var sb strings.Builder

	for i, block := range blocks {
		if i > 0 {
			sb.WriteString("\n")
		}

		fmt.Fprintf(&sb, "Lines %s\n", block.RangeText())

		if block.Commit.ShortHash != "" {
			fmt.Fprintf(&sb, "Commit: %s\n", block.Commit.ShortHash)
		}
		if block.Commit.Author != "" {
			fmt.Fprintf(&sb, "Author: %s\n", block.Commit.Author)
		}
		if block.Commit.WhenText != "" {
			fmt.Fprintf(&sb, "When: %s\n", block.Commit.WhenText)
		}
		if block.Commit.Subject != "" {
			fmt.Fprintf(&sb, "Subject: %s\n", block.Commit.Subject)
		}

		if block.Entire != nil {
			if block.Entire.CheckpointID != "" {
				fmt.Fprintf(&sb, "Entire Checkpoint: %s\n", block.Entire.CheckpointID)
			}
			if block.Entire.Agent != "" {
				fmt.Fprintf(&sb, "Entire Agent: %s\n", block.Entire.Agent)
			}
			if block.Entire.Summary != "" {
				fmt.Fprintf(&sb, "Entire Summary: %s\n", block.Entire.Summary)
			}
		}

		if len(block.CodeLines) > 0 {
			sb.WriteString("Code:\n")
			for _, line := range block.CodeLines {
				fmt.Fprintf(&sb, "  %s\n", line)
			}
		}
	}

	return sb.String()
}

